# Libraries :
from pathlib import Path
import numpy as np
import pandas as pd

####################################
### Configuration  ###
####################################

SEED = 42

# Create a random generator object
rng = np.random.default_rng(SEED)

# Input Path
SCRIPT_DIR = Path(__file__).resolve().parent

# "members_full.csv" and "devices_full.csv" files are exported from PostgreSQL after loading members and devices.
# They include the real surrogate keys generated by the database: member_id and device_id
MEMBERS_PATH = SCRIPT_DIR / "members_full.csv"
DEVICES_PATH = SCRIPT_DIR / "devices_full.csv"

# Output Path
REPO_ROOT = Path(__file__).resolve().parents[1]  # REPO_ROOT => top of git project CWD
OUTPUT_PATH = REPO_ROOT / "data" / "raw" / "member_devices_raw.csv"


#############################
### Dictionaries of lists ###
#############################

# The members_dict will store the real member_id generated by PostgreSQL
members_dict = {'member_id': [],
                'length': ""
}

# The devices_dict will store the real device_id generated by PostgreSQL
devices_dict = {'device_id': [],
                'length': ""
}

# The member_devices_dict will store the relationship between a member and a device.
# Later, it will be converted into a tabular format using a dataframe.
member_devices_dict = {'member_id': [],
                       'device_id': [],
                       'assigned_at': [],
                       'unassigned_at': []
}


##############################
# Load Functions
##############################


# load_members function reads members_full.csv and stores member_id values into members_dict
def load_members():

    dataframe = pd.read_csv(MEMBERS_PATH)
    
    # Insert "member_id" into members_dict through pandas loop (iterrows) 
    # Ignore undercore (_), it refers to index label.
    for _, row in dataframe.iterrows():
       members_dict['member_id'].append(int(row['member_id']))

    # Determine how many members were loaded and store in length key
    members_dict['length'] = len(members_dict['member_id'])
    
    
    return



# load_devices function reads devices_full.csv and stores device_id values into devices_dict
def load_devices():

    dataframe = pd.read_csv(DEVICES_PATH)
        
    # Insert "device_id" into devices_dict through pandas loop (iterrows) 
    # Ignore undercore (_), it refers to index label.
    for _, row in dataframe.iterrows():
        devices_dict['device_id'].append(int(row['device_id']))

    # Determine how many devices were loaded
    devices_dict['length'] = len(devices_dict['device_id'])

    
    return



# assign_devices_to_members Function assign one device to one member
# assignment is randomized and gets a random date-time
# unassigned_at stays None (device still active)
def assign_devices_to_members():

    # Create a copy of members and devices lists
    member_ids = members_dict['member_id'].copy()
    device_ids = devices_dict['device_id'].copy()
  
    #Shuffle "member_ids" and "device_ids" mix values
    rng.shuffle(member_ids)
    rng.shuffle(device_ids)

    
    
    # Determine how many assignments can be created
    # If one list is shorter, use the shortest length
    total_assignments = min(len(member_ids), len(device_ids))
    
    # Base timestamp used to generate assigned_at
    # Devices will be assigned at midnight or "start of the day" (easer debugging and clinear time arithmetic)
    base_date = pd.Timestamp("2026-03-01 00:00:00", tz="UTC")
    
    # 100 members and 100 devices will create 100 assignments
    for i in range(total_assignments):
        random_days = int(rng.integers(0, 31))      # 0 to 30 days after base date
        random_hours = int(rng.integers(0, 24))     # 0 to 23 hours
        random_minutes = int(rng.integers(0, 60))   # 0 to 59 minutes
        
        # Generate an assignment timestamp by adding a random offset
        # (days, hours, minutes) to the base_date     
        assigned_at = base_date + pd.Timedelta(days=random_days,
                                               hours=random_hours,
                                               minutes=random_minutes)

        # Store values in member_devices dictionary
        member_devices_dict['member_id'].append(member_ids[i])
        member_devices_dict['device_id'].append(device_ids[i])
        member_devices_dict['assigned_at'].append(assigned_at.isoformat()) # Use isoformat for asure timezone consistency and safety
        member_devices_dict['unassigned_at'].append(None)
         
    return


###############
###  MAIN   ###
###############

load_members()   # Load real member_id values from members_full.csv
load_devices()   # Load real device_id values from devices_full.csv
assign_devices_to_members()  # This function simulates devices being assigned to members at different moments in time

# Generate a dataframe and store in the output_path
dataframe = pd.DataFrame(member_devices_dict)
dataframe.to_csv(OUTPUT_PATH, index=False)  # Dataframe will be saved in a .csv file
